package com.library.config;
import com.library.entity.*; import com.library.repository.*; import org.springframework.stereotype.Component; import org.springframework.boot.CommandLineRunner; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal;
@Component
public class Bootstrap implements CommandLineRunner {
 private final UserRepository users; private final BookRepository books; private final ChapterRepository chapters; private final PasswordEncoder encoder;
 @Value("${library.admin.username}") String username; @Value("${library.admin.password}") String password;
 public Bootstrap(UserRepository u,BookRepository b,ChapterRepository c,PasswordEncoder e){users=u;books=b;chapters=c;encoder=e;}
 @Override @Transactional public void run(String... args){
  if(users.findByRoleOrderByIdDesc("ADMIN").isEmpty()) {if(password==null||password.length()<12||password.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72)throw new IllegalStateException("Set ADMIN_PASSWORD to 12+ characters (maximum 72 UTF-8 bytes) before first startup");var u=new LibraryUser();u.setFullName("Library Administrator");u.setUsername(username);u.setEmail("admin@library.local");u.setPasswordHash(encoder.encode(password));u.setRole("ADMIN");users.save(u);}
  if(books.count()==0){
   seed("The Cartographer’s Lantern","Mira Vale","Literary fiction","An original short story about a mapmaker, a missing road, and the places we choose to call home.","12.00",new String[]{"The road at the edge of town","A light across the water","A place on the map"},new String[]{
    "Every evening, Ada lit the brass lantern above her map shop. Its small circle of gold fell across streets she had drawn a hundred times: Mill Lane, the market square, the crooked bridge. Yet on the first evening of autumn, a new road appeared on the oldest map. It began behind the bakery and ended in a patch of blank paper.\nShe walked to the bakery with her lantern. Between two familiar walls lay a narrow path she had never seen. The baker stood at his door, dusting flour from his sleeves. ‘It has always been there,’ he said. ‘You have always been busy.’\nAda followed the path until the town’s bells sounded distant. At its end was a lake, still as polished glass. On the far shore, a window shone. She took out her pencil. For the first time in years, she did not know what to draw.",
    "A ferryman waited beside a boat with blue-painted oars. He asked for no coin, only the name of somewhere she missed. Ada thought of the house where her mother had taught her to fold paper boats. She said its name softly, and the ferryman pushed away from shore.\nThe house across the lake was not that house. It was a reading room. Shelves held notebooks in a hundred different hands. A woman at the desk offered Ada tea. ‘People leave directions here,’ she explained. ‘To places that matter. We keep them until someone is ready to look.’\nAda found a notebook with her mother’s handwriting. Inside was a single instruction: When you are lost, ask someone what they can see. Ada closed the notebook and watched the lake turn silver under the moon.",
    "At dawn, Ada returned to town. She did not put the reading room on her map. Instead, she drew the narrow path behind the bakery, carefully leaving room around it for discoveries she could not yet name.\nShe moved her worktable beside the open door. When customers came for directions, she asked where they hoped to go, and listened to the whole answer. Some wanted the station. Some wanted a place to sit. One child wanted to know where the swallows slept.\nThat evening, she lit the lantern as usual. The light reached the bakery wall, the first stones of the path, and a little farther than it had the day before. Ada opened a fresh sheet of paper. At the top she wrote: A map is an invitation. Beneath it, she began."});
   seed("A Garden of Small Hours","Elias Reed","Nature & essays","Two original reflections on the quiet pleasures of growing things and paying attention.","8.50",new String[]{"Before the city wakes","What the soil remembers"},new String[]{
    "The garden is smallest at noon, when every boundary is visible. Before sunrise it has no edges. The rosemary becomes a small forest, and the empty watering can is a moon caught in a bucket. I go outside without my phone and listen for the first bird.\nThere is no achievement in this ritual. The tomatoes do not grow faster because I watch them. But I notice the new leaf, the snail’s silver trail, the place where yesterday’s rain has gathered. Attention is a kind of hospitality: it makes room for things that cannot ask to be seen.\nWhen the buses begin on the avenue, I fill the watering can. By then, the garden has returned to its ordinary size. I carry its larger version into the day.",
    "Last winter I buried a handful of beans beneath the kitchen window. I forgot their variety and misplaced the packet. In spring, green shoots arrived without labels. They climbed the twine as if following instructions older than language.\nMy neighbor said the soil remembered what I had forgotten. I liked that explanation. The garden keeps a patient record: fallen leaves become shelter, kitchen scraps become soil, and mistakes become the things we do differently next year.\nAt harvest, I saved six beans in an envelope. I wrote the date and, beneath it, a reminder: begin again. Outside, the evening light settled on the empty vines. Nothing in the garden was finished; everything was making room."});
  }
 }
 private void seed(String title,String author,String genre,String description,String price,String[] titles,String[] contents){var b=new Book();b.setTitle(title);b.setAuthor(author);b.setGenre(genre);b.setDescription(description);b.setPrice(new BigDecimal(price));b.setStatus("PUBLISHED");b.setPublicationDate(java.time.LocalDate.of(2026,1,1));books.save(b);for(int i=0;i<titles.length;i++){var c=new Chapter();c.setBookId(b.getId());c.setChapterNumber(i+1);c.setTitle(titles[i]);c.setContent("<p>"+contents[i].replace("\n","</p><p>")+"</p>");chapters.save(c);}}
}
